Projection.mort_max_age:
def mort_max_age():
    """The last age of the mortality table at the policy's sex."""
    return int(data.mort_table().loc[sex()].index.max())

Projection.lapse_at_completion:
def lapse_at_completion():
    """The lapse rate the grade converges to at the end of the payment term."""
    return float(data.lapse_table().loc[Segment.at_completion, "lapse_rate"])

Projection.lapse_first_year:
def lapse_first_year():
    """The first-year lapse rate (the start of the log-linear grade)."""
    return float(data.lapse_table().loc[Segment.first_year, "lapse_rate"])

Projection.lapse_post_payment:
def lapse_post_payment():
    """The lapse rate after the payment term."""
    return float(data.lapse_table().loc[Segment.post_payment, "lapse_rate"])

Projection.inc_schedule:
def inc_schedule():
    """The base incidence rates at the policy's sex, by pivot age."""
    return data.incidence_table().loc[sex()]

Projection.inc_ages:
def inc_ages():
    """The pivot ages of :func:`inc_schedule`, ascending."""
    return list(inc_schedule().index)

Projection.tier_share_schedule:
def tier_share_schedule():
    """The tier shares at the policy's sex, by pivot age."""
    return data.tier_share_table().loc[sex()]

Projection.tier_share_ages:
def tier_share_ages():
    """The pivot ages of :func:`tier_share_schedule`, ascending."""
    return list(tier_share_schedule().index)
